export async function seedNist80053Controls(
  prisma: PrismaClient, frameworkId: string, organizationId: string,
): Promise<{ familyCount: number; controlCount: number }> {
  // Phase 1: Create family-level controls
  const familyMap = new Map<string, string>();
  for (const family of NIST_800_53_FAMILIES) {
    const id = randomUUID();
    const text = textFor(family.controlId, family.title);
    await prisma.control.create({
      data: {
        id,
        organizationId,
        frameworkId,
        controlId: family.controlId,
        title: family.title,
        description: text.description,
        guidance: text.guidance,
        parentControlId: null,
        baselines: null,
        isActive: true,
        updatedAt: new Date(),
      },
    });
    familyMap.set(family.controlId, id);
  }

  // Phase 2: Create base controls (no parenthetical in ID)
  const baseMap = new Map<string, string>();
  for (const control of NIST_800_53_CONTROLS) {
    if (control.parentId !== null) continue; // Skip enhancements
    const id = randomUUID();
    const familyUuid = familyMap.get(control.familyId);
    const text = textFor(control.controlId, control.title);
    await prisma.control.create({
      data: {
        id,
        organizationId,
        frameworkId,
        controlId: control.controlId,
        title: control.title,
        description: text.description,
        guidance: text.guidance,
        parentControlId: familyUuid ?? null,
        baselines: control.baselines || null,
        isActive: true,
        updatedAt: new Date(),
      },
    });
    baseMap.set(control.controlId, id);
  }

  // Phase 3: Create enhancements (parentId points to base control)
  let enhancementCount = 0;
  for (const control of NIST_800_53_CONTROLS) {
    if (control.parentId === null) continue; // Skip base controls
    const parentUuid = baseMap.get(control.parentId);
    const text = textFor(control.controlId, control.title);
    await prisma.control.create({
      data: {
        id: randomUUID(),
        organizationId,
        frameworkId,
        controlId: control.controlId,
        title: control.title,
        description: text.description,
        guidance: text.guidance,
        parentControlId: parentUuid ?? null,
        baselines: control.baselines || null,
        isActive: true,
        updatedAt: new Date(),
      },
    });
    enhancementCount++;
  }

  return { familyCount: NIST_800_53_FAMILIES.length, controlCount: NIST_800_53_CONTROLS.length };
}

